export const getVibePlaylists = () => VIBE_PLAYLISTS;


export const fetchCategoryTracks = async (categoryId, limit = 20) => {
  const cat = CATALOG_CATEGORIES.find(c => c.id === categoryId);
  if (cat && cat.tracks && cat.tracks.length > 0) {
    return cat.tracks.map(t => {
      const stream = t.streamUrl || PERMANENT_STREAM_MAP[t.title] || '';
      return {
        id: t.id || (t.ytId ? `ytm-${t.ytId}` : `pulse-${Math.random()}`),
        ytId: t.ytId,
        title: t.title,
        artist: t.artist,
        coverUrl: t.cover || t.coverUrl || (t.ytId ? `https://i.ytimg.com/vi/${t.ytId}/hqdefault.jpg` : './music-cover.svg'),
        duration: t.duration || 220,
        streamUrl: stream,
        source: stream ? "Studio Master Audio (320kbps)" : "Studio Master Audio (YouTube)"
      };
    }).slice(0, limit);
  }

  // Fallback search
  try {
    if (typeof window !== 'undefined' && window.musicService?.searchTracks) {
      return await window.musicService.searchTracks(categoryId.replace('cat-', ''), limit);
    }
  } catch (e) {}

  return [];
};

/**
 * Searches across all built-in catalog categories, language playlists, and curated tracks
 */

/**
 * Search artists across curated registry and full catalog
 */
export function searchArtists(query) {
  if (!query || typeof query !== 'string' || !query.trim()) return [];
  const q = query.trim().toLowerCase();
  const cleanQ = q.replace(/[^a-z0-9\s]/g, ' ').replace(/\s+/g, ' ').trim();
  const qTokens = cleanQ.split(' ').filter(w => w.length >= 2);

  const results = [];
  const seen = new Set();

  const addCandidate = (name, genre, avatar, banner, followers, rank, bonus = 0) => {
    if (!name || typeof name !== 'string') return;
    const cleanName = name.trim();
    if (!cleanName || cleanName.length < 2) return;
    const key = cleanName.toLowerCase();
    if (seen.has(key)) return;

    const norm = key.replace(/[^a-z0-9\s]/g, ' ').replace(/\s+/g, ' ').trim();
    let score = 0;

    if (norm === cleanQ) {
      score = 100;
    } else if (norm.startsWith(cleanQ)) {
      score = 90;
    } else if (cleanQ.startsWith(norm)) {
      score = 85;
    } else if (norm.includes(cleanQ)) {
      score = 75;
    } else {
      const matchTokens = qTokens.filter(t => norm.includes(t));
      if (matchTokens.length > 0) {
        score = 45 + (matchTokens.length * 15);
      }
    }

    if (score > 0) {
      score += bonus;
      seen.add(key);
      results.push({
        id: cleanName.toLowerCase().replace(/[^a-z0-9]/g, '-'),
        name: cleanName,
        genre: genre || 'Master Artist',
        avatar: avatar || banner || `https://api.dicebear.com/7.x/initials/svg?seed=${encodeURIComponent(cleanName)}&backgroundColor=8b5cf6`,
        banner: banner || avatar || `https://api.dicebear.com/7.x/initials/svg?seed=${encodeURIComponent(cleanName)}&backgroundColor=8b5cf6`,
        followersCount: followers || '15,000,000',
        worldRank: rank || '#10 Globally',
        score
      });
    }
  };

  // 1b. Search cached dynamic artists from localStorage
  try {
    if (typeof localStorage !== 'undefined') {
      for (let i = 0; i < localStorage.length; i++) {
        const k = localStorage.key(i);
        if (k && k.startsWith('pulse_artist_')) {
          try {
            const cached = JSON.parse(localStorage.getItem(k));
            if (cached && cached.name) {
              addCandidate(cached.name, cached.worldRank || 'Verified Artist', cached.avatar || cached.banner, cached.banner, cached.followersCount, cached.worldRank, 25);
            }
          } catch (e) {}
        }
      }
    }
  } catch (e) {}

  // 1. Search all verified artists in ARTIST_DATABASE first
  if (typeof ARTIST_DATABASE === 'object' && ARTIST_DATABASE) {
    Object.values(ARTIST_DATABASE).forEach(artist => {
      addCandidate(artist.name, artist.worldRank || 'Verified Master', artist.banner, artist.banner, artist.followersCount, artist.worldRank, 30);
    });
  }

  // 2. Search Featured Artists
  const featured = getFeaturedArtists();
  featured.forEach(a => addCandidate(a.name, a.genre, a.avatar, a.avatar, '15,000,000', '#10 Globally', 20));

  // 3. Search tracks in catalog for individual solo artists
  if (Array.isArray(CATALOG_CATEGORIES)) {
    CATALOG_CATEGORIES.forEach(c => {
      (c.tracks || []).forEach(t => {
        if (t.artist) {
          const parts = t.artist.split(/[,&+]|feat\.|ft\.|x/i).map(s => s.trim()).filter(Boolean);
          parts.forEach(p => addCandidate(p, t.genre || 'Master Artist', t.coverUrl, t.coverUrl, '10,000,000', '#25 Globally', 0));
        }
      });
    });
  }

  results.sort((a, b) => b.score - a.score);
  return results.slice(0, 8);
}

export function searchCatalogTracks(query) {
  if (!query || typeof query !== 'string' || query.trim().length === 0) return [];
  const q = query.trim().toLowerCase();
  const cleanQ = q.replace(/!/g, 'i').replace(/\$/g, 's').replace(/@/g, 'a').replace(/[^a-z0-9\s]/g, ' ').replace(/\s+/g, ' ').trim();
  const qTokens = cleanQ.split(' ').filter(w => w.length >= 2);
  const matched = [];
  const seen = new Set();

  const add = (t, src) => {
    if (!t || !t.title) return;
    const rawT = (t.title || '').toLowerCase();
    const rawA = (t.artist || '').toLowerCase();
    const title = rawT.replace(/!/g, 'i').replace(/\$/g, 's').replace(/@/g, 'a').replace(/[^a-z0-9\s]/g, ' ').replace(/\s+/g, ' ').trim();
    const artist = rawA.replace(/!/g, 'i').replace(/\$/g, 's').replace(/@/g, 'a').replace(/[^a-z0-9\s]/g, ' ').replace(/\s+/g, ' ').trim();
    const genre = (t.genre || '').toLowerCase().trim();
    const source = (src || '').toLowerCase().trim();

    // Check title match
    const titleMatch = title.includes(cleanQ) || (cleanQ.length >= 3 && cleanQ.includes(title));
    
    // Check artist match
    const artistMatch = artist.includes(cleanQ) || (cleanQ.length >= 3 && cleanQ.includes(artist));
    
    // Token overlap
    const tokensInTitle = qTokens.filter(tok => title.includes(tok)).length;
    const tokensInArtist = qTokens.filter(tok => artist.includes(tok)).length;
    const totalTokensInTrack = qTokens.filter(tok => title.includes(tok) || artist.includes(tok)).length;

    // Strict multi-word matching: if query has multiple words, only match if title matches OR (artist matches and title tokens match)
    let isMatch = false;
    if (qTokens.length <= 1) {
      isMatch = titleMatch || artistMatch || genre === cleanQ || source === cleanQ;
    } else {
      if (titleMatch) {
        isMatch = true;
      } else if (artistMatch && tokensInTitle > 0) {
        isMatch = true;
      } else if (cleanQ.includes(artist) && tokensInTitle > 0) {
        isMatch = true;
      } else if (tokensInTitle >= Math.min(qTokens.length, 2)) {
        isMatch = true;
      } else if (cleanQ.length <= artist.length + 3 && cleanQ.includes(artist)) {
        // Query is essentially just the artist name with minor filler
        isMatch = true;
      }
    }

    if (isMatch) {
      const key = `${title}___${artist}`;
      if (!seen.has(key)) {
        seen.add(key);
        const stream = t.streamUrl || PERMANENT_STREAM_MAP[t.title] || '';
        matched.push({
          id: t.id || (t.ytId ? `ytm-${t.ytId}` : `cat-${Math.random()}`),
          ytId: t.ytId,
          title: t.title,
          artist: t.artist,
          album: t.album || 'Pulse Master Catalog',
          coverUrl: t.coverUrl || t.cover || (t.ytId ? `https://i.ytimg.com/vi/${t.ytId}/hqdefault.jpg` : './music-cover.svg'),
          duration: t.duration || 220,
          streamUrl: stream,
          source: stream ? 'Studio Master Audio (320kbps)' : (src || 'Studio Master Audio (YouTube)')
        });
      }
    }
  };

  // 1. Search in CATALOG_CATEGORIES
  CATALOG_CATEGORIES.forEach(cat => {
    (cat.tracks || []).forEach(t => add(t, cat.title));
  });

  // 2. Search in LANGUAGE_PLAYLISTS (English, Hindi, Punjabi, Kannada, Tamil, Telugu, Marathi, Gujarati, Spanish, K-Pop)
  LANGUAGE_PLAYLISTS.forEach(lang => {
    (lang.tracks || []).forEach(t => add(t, lang.meta.title));
  });

  // 3. Search in Quick Picks & Curated Playlists
  getQuickPicks(30).forEach(t => add(t, 'Quick Picks'));
  getCuratedPlaylists().forEach(pl => {
    (pl.tracks || []).forEach(t => add(t, pl.title));
  });
  getMoviePlaylists().forEach(pl => {
    (pl.tracks || []).forEach(t => add(t, pl.title));
  });
  getVibePlaylists().forEach(pl => {
    (pl.tracks || []).forEach(t => add(t, pl.title));
  });

  return matched;
}

export const getArtistDetails = (artistName) => {
  const normalized = (artistName || '').toLowerCase().trim();
  const db = ARTIST_DATABASE;

  // 1. Direct or fuzzy lookup in curated artist registry
  let foundKey = Object.keys(db).find(k => {
    const art = db[k];
    const aName = art.name.toLowerCase();
    return normalized === aName || normalized.includes(k) || aName.includes(normalized) || normalized.includes(aName);
  });

  // Handle common aliases
  if (!foundKey) {
    if (normalized.includes('arijit')) foundKey = 'arijit-singh';
    else if (normalized.includes('atif')) foundKey = 'atif-aslam';
    else if (normalized.includes('dhillon')) foundKey = 'ap-dhillon';
    else if (normalized.includes('dosanjh') || normalized.includes('diljit')) foundKey = 'diljit-dosanjh';
    else if (normalized.includes('weeknd')) foundKey = 'the-weeknd';
    else if (normalized.includes('swift')) foundKey = 'taylor-swift';
    else if (normalized.includes('billie') || normalized.includes('eilish')) foundKey = 'billie-eilish';
    else if (normalized.includes('sabrina') || normalized.includes('carpenter')) foundKey = 'sabrina-carpenter';
    else if (normalized.includes('hasan raheem') || (normalized.includes('hasan') && !normalized.includes('hannan'))) foundKey = 'hasan-raheem';
    else if (normalized.includes('kaifi') || normalized.includes('khalil')) foundKey = 'kaifi-khalil';
    else if (normalized.includes('appaji') || normalized.includes('ganapathy') || normalized.includes('srimatha')) foundKey = 'appaji';
    else if (normalized.includes('coldplay')) foundKey = 'coldplay';
    else if (normalized.includes('eminem')) foundKey = 'eminem';
    else if (normalized.includes('sheeran')) foundKey = 'ed-sheeran';
    else if (normalized.includes('anirudh')) foundKey = 'anirudh-ravichander';
    else if (normalized.includes('sethi') || normalized.includes('ali')) foundKey = 'ali-sethi';
    else if (normalized.includes('imagine') || normalized.includes('dragons')) foundKey = 'imagine-dragons';
    else if (normalized.includes('bruno') || normalized.includes('mars')) foundKey = 'bruno-mars';
    else if (normalized.includes('adele')) foundKey = 'adele';
    else if (normalized.includes('linkin') || normalized.includes('park')) foundKey = 'linkin-park';
    else if (normalized.includes('dua') || normalized.includes('lipa')) foundKey = 'dua-lipa';
    else if (normalized.includes('bunny') || normalized.includes('benito')) foundKey = 'bad-bunny';
    else if (normalized.includes('shreya') || normalized.includes('ghoshal')) foundKey = 'shreya-ghoshal';
    else if (normalized.includes('sonu') || normalized.includes('nigam')) foundKey = 'sonu-nigam';
    else if (normalized.includes('kk') || normalized.includes('kay kay') || normalized.includes('krishnakumar')) foundKey = 'kk';
    else if (normalized.includes('sriram')) foundKey = 'sid-sriram';
    else if (normalized.includes('moosewala') || normalized.includes('sidhu')) foundKey = 'sidhu-moosewala';
    else if (normalized.includes('aujla') || normalized.includes('karan')) foundKey = 'karan-aujla';
    else if (normalized.includes('drake') || normalized.includes('champagnepapi')) foundKey = 'drake';
    else if (normalized.includes('kendrick') || normalized.includes('lamar') || normalized.includes('kdot')) foundKey = 'kendrick-lamar';
    else if (normalized.includes('posty') || normalized.includes('post malone')) foundKey = 'post-malone';
    else if (normalized.includes('bieber') || normalized.includes('justin')) foundKey = 'justin-bieber';
    else if (normalized.includes('ariana') || normalized.includes('grande')) foundKey = 'ariana-grande';
    else if (normalized.includes('bts') || normalized.includes('bangtan')) foundKey = 'bts';
    else if (normalized.includes('travis') || normalized.includes('scott') || normalized.includes('la flame')) foundKey = 'travis-scott';
    else if (normalized.includes('kishore') || normalized.includes('kumar')) foundKey = 'kishore-kumar';
    else if (normalized.includes('lata') || normalized.includes('mangeshkar')) foundKey = 'lata-mangeshkar';
    else if (normalized.includes('rahman') || normalized.includes('ar rahman') || normalized.includes('a.r. rahman')) foundKey = 'a-r-rahman';
    else if (normalized.includes('badshah')) foundKey = 'badshah';
    else if (normalized.includes('honey') || normalized.includes('yo yo')) foundKey = 'yo-yo-honey-singh';
    else if (normalized.includes('neha') || normalized.includes('kakkar')) foundKey = 'neha-kakkar';
    else if (normalized.includes('sunidhi') || normalized.includes('chauhan')) foundKey = 'sunidhi-chauhan';
    else if (normalized.includes('jubin') || normalized.includes('nautiyal')) foundKey = 'jubin-nautiyal';
    else if (normalized.includes('nusrat') || (normalized.includes('khan') && normalized.includes('fateh'))) foundKey = 'nusrat-fateh-ali-khan';
    else if (normalized.includes('rahat')) foundKey = 'rahat-fateh-ali-khan';
    else if (normalized.includes('blackpink')) foundKey = 'blackpink';
    else if (normalized.includes('styles') || normalized.includes('harry')) foundKey = 'harry-styles';
    else if (normalized.includes('olivia') || normalized.includes('rodrigo')) foundKey = 'olivia-rodrigo';
    else if (normalized.includes('gaga') || normalized.includes('lady')) foundKey = 'lady-gaga';
    else if (normalized.includes('puth') || normalized.includes('charlie')) foundKey = 'charlie-puth';
    else if (normalized.includes('darshan') || normalized.includes('raval')) foundKey = 'darshan-raval';
    else if (normalized.includes('anuv') || normalized.includes('jain')) foundKey = 'anuv-jain';
    else if (normalized.includes('kuhad') || normalized.includes('prateek')) foundKey = 'prateek-kuhad';
    else if (normalized.includes('mendes') || normalized.includes('shawn')) foundKey = 'shawn-mendes';
    else if (normalized.includes('rihanna') || normalized.includes('riri')) foundKey = 'rihanna';
    else if (normalized.includes('beyonce') || normalized.includes('beyoncé') || normalized.includes('queen bey')) foundKey = 'beyoncé';
    else if (normalized.includes('shakira')) foundKey = 'shakira';
    else if (normalized.includes('zayn') || normalized.includes('malik')) foundKey = 'zayn';
    else if (normalized.includes('mohit') && normalized.includes('chauhan')) foundKey = 'mohit-chauhan';
    else if (normalized.includes('pritam')) foundKey = 'pritam';
  }

  // 1B. Check LocalStorage cache for dynamically resolved artist profile
  try {
    if (typeof localStorage !== 'undefined') {
      const cleanKey = normalized.replace(/[^a-z0-9]/g, '-');
      const cachedStr = localStorage.getItem(`pulse_artist_${cleanKey}`);
      if (cachedStr) {
        const cached = JSON.parse(cachedStr);
        if (cached && cached.topTracks && cached.topTracks.length > 0) {
          return cached;
        }
      }
    }
  } catch (e) {}

  if (foundKey && db[foundKey]) {
    const data = db[foundKey];
    return {
      id: foundKey,
      name: data.name,
      monthlyListeners: data.monthlyListeners,
      followersCount: data.followersCount || '15,000,000',
      worldRank: data.worldRank,
      banner: data.banner,
      avatar: data.banner,
      topTracks: data.topTracks,
      bio: data.bio,
      socials: data.socials,
      tourInfo: data.tourInfo,
      albums: [
        { title: "Greatest Studio Hits", year: "2024", type: "Album", coverUrl: data.topTracks[0]?.coverUrl || data.banner },
        { title: "Live Concert Sessions", year: "2023", type: "Live Album", coverUrl: data.topTracks[1]?.coverUrl || data.banner }
      ],
      singles: [
        { title: data.topTracks[0]?.title || "Latest Single", year: "2024", type: "Single", coverUrl: data.topTracks[0]?.coverUrl || data.banner }
      ],
      similarArtists: getCuratedSimilarArtists(foundKey, data.name)
    };
  }

    // 2. Dynamic Fallback: Gather all songs matching artistName strictly from full catalog
  const matchedTracks = [];
  const seenTrackIds = new Set();
  const scanForArtist = (tracks) => {
    (tracks || []).forEach(t => {
      if (!t || !t.title || seenTrackIds.has(t.id || t.title)) return;
      const art = (t.artist || '').toLowerCase();
      if (art.includes(normalized) || normalized.includes(art)) {
        seenTrackIds.add(t.id || t.title);
        matchedTracks.push({
          id: t.id,
          ytId: t.ytId || (t.id.startsWith('ytm-') ? t.id.replace('ytm-', '') : ''),
          title: t.title,
          artist: t.artist || artistName,
          album: t.album || t.movie || 'Studio Master',
          coverUrl: t.coverUrl || t.cover || (t.ytId ? `https://i.ytimg.com/vi/${t.ytId}/hqdefault.jpg` : './music-cover.svg'),
          duration: t.duration || 215,
          plays: t.plays || '1,200,000'
        });
      }
    });
  };

  if (Array.isArray(CATALOG_CATEGORIES)) CATALOG_CATEGORIES.forEach(cat => scanForArtist(cat.tracks));
  if (typeof LANGUAGE_PLAYLISTS === 'object' && LANGUAGE_PLAYLISTS) Object.values(LANGUAGE_PLAYLISTS).forEach(pl => scanForArtist(pl.tracks));
  if (Array.isArray(MOVIE_PLAYLISTS)) MOVIE_PLAYLISTS.forEach(pl => scanForArtist(pl.tracks));
  if (Array.isArray(VIBE_PLAYLISTS)) VIBE_PLAYLISTS.forEach(pl => scanForArtist(pl.tracks));

  // If no tracks found in catalog, generate an authentic primary anthem for this artist
  if (matchedTracks.length === 0) {
    matchedTracks.push({
      id: `ytm-artist-${artistName.toLowerCase().replace(/[^a-z0-9]/g, '-')}-1`,
      ytId: 'dQw4w9WgXcQ',
      title: `${artistName} Master Collection`,
      artist: artistName,
      album: 'Studio Master Collection',
      coverUrl: `https://api.dicebear.com/7.x/initials/svg?seed=${encodeURIComponent(artistName)}&backgroundColor=8b5cf6`,
      duration: 220,
      plays: '1,450,000'
    });
  }

  const top10 = matchedTracks.slice(0, 10);
  const cleanHandle = artistName.toLowerCase().replace(/[^a-z0-9]/g, '');
  
  // Find authentic avatar from featured artists if present, or first song cover, or initials avatar (NEVER The Weeknd photo!)
  const featuredArtistMatch = getFeaturedArtists().find(a => a.name.toLowerCase() === normalized || a.name.toLowerCase().includes(normalized));
  const banner = featuredArtistMatch?.avatar || top10[0]?.coverUrl || `https://api.dicebear.com/7.x/initials/svg?seed=${encodeURIComponent(artistName)}&backgroundColor=8b5cf6`;

  const similarArtists = getCuratedSimilarArtists('', artistName);

  return {
    id: artistName.toLowerCase().replace(/\s+/g, '-'),
    name: artistName,
    monthlyListeners: "18,500,000",
    followersCount: "12,400,000",
    worldRank: "#12 Globally",
    banner,
    avatar: banner,
    topTracks: top10,
    bio: `${artistName} is a celebrated recording artist whose high-fidelity studio productions and live performances have captivated music lovers worldwide. Explore their verified top 10 songs, official releases, and concert tours on Pulse Music.`,
    socials: {
      instagram: `https://www.instagram.com/${cleanHandle}/`,
      x: `https://x.com/${cleanHandle}`,
      facebook: `https://www.facebook.com/${cleanHandle}/`,
      youtube: `https://www.youtube.com/results?search_query=${encodeURIComponent(artistName + ' official channel')}`
    },
    tourInfo: {
      tourName: `${artistName} Live World Tour`,
      status: "Tickets Live",
      dates: "Upcoming Arena & Stadium Dates Worldwide",
      ticketUrl: `https://in.bookmyshow.com/explore/events`
    },
    albums: [
      { title: "Greatest Studio Hits", year: "2024", type: "Album", coverUrl: banner },
      { title: "Live Concert Sessions", year: "2023", type: "Live Album", coverUrl: top10[1]?.coverUrl || banner }
    ],
    singles: [
      { title: top10[0]?.title || "Latest Single", year: "2024", type: "Single", coverUrl: banner }
    ],
    similarArtists
  };
};

export function findCatalogCover(title, artist) {
  if (!title) return null;
  const cleanT = (title || '').toLowerCase().replace(/[^a-z0-9]/g, '');
  const cleanA = (artist || '').toLowerCase().replace(/[^a-z0-9]/g, '');

  // 1. Check ARTIST_DATABASE top tracks
  if (typeof ARTIST_DATABASE === 'object' && ARTIST_DATABASE) {
    for (const art of Object.values(ARTIST_DATABASE)) {
      if (Array.isArray(art.topTracks)) {
        for (const t of art.topTracks) {
          const tClean = (t.title || '').toLowerCase().replace(/[^a-z0-9]/g, '');
          if (tClean === cleanT || (cleanT.length >= 4 && (tClean.includes(cleanT) || cleanT.includes(tClean)))) {
            const c = t.coverUrl || t.cover;
            if (c && !c.includes('music-cover.svg')) return c;
          }
        }
      }
    }
  }

  // 2. Check CATALOG_CATEGORIES
  if (Array.isArray(CATALOG_CATEGORIES)) {
    for (const cat of CATALOG_CATEGORIES) {
      if (Array.isArray(cat.tracks)) {
        for (const t of cat.tracks) {
          const tClean = (t.title || '').toLowerCase().replace(/[^a-z0-9]/g, '');
          if (tClean === cleanT || (cleanT.length >= 4 && (tClean.includes(cleanT) || cleanT.includes(tClean)))) {
            const c = t.coverUrl || t.cover;
            if (c && !c.includes('music-cover.svg')) return c;
          }
        }
      }
    }
  }

  // 3. Check LANGUAGE_PLAYLISTS, MOVIE_PLAYLISTS, VIBE_PLAYLISTS
  const allPlaylists = [
    ...(typeof LANGUAGE_PLAYLISTS === 'object' ? Object.values(LANGUAGE_PLAYLISTS) : []),
    ...(Array.isArray(MOVIE_PLAYLISTS) ? MOVIE_PLAYLISTS : []),
    ...(Array.isArray(VIBE_PLAYLISTS) ? VIBE_PLAYLISTS : [])
  ];
  for (const pl of allPlaylists) {
    if (Array.isArray(pl.tracks)) {
      for (const t of pl.tracks) {
        const tClean = (t.title || '').toLowerCase().replace(/[^a-z0-9]/g, '');
        if (tClean === cleanT || (cleanT.length >= 4 && (tClean.includes(cleanT) || cleanT.includes(tClean)))) {
          const c = t.coverUrl || t.cover;
          if (c && !c.includes('music-cover.svg')) return c;
        }
      }
    }
  }

  return null;
}

export const getNewReleasesShelf = () => {
  let tracks = [];
  if (typeof window !== 'undefined' && window.newReleasesService && typeof window.newReleasesService.getCachedNewReleases === 'function') {
    tracks = window.newReleasesService.getCachedNewReleases();
  } else {
    const cat = CATALOG_CATEGORIES.find(c => c.id === 'cat-new-releases');
    tracks = cat ? cat.tracks : [];
  }
  return (tracks || []).map(t => ({
    ...t,
    coverUrl: t.coverUrl || t.cover || (t.ytId ? `https://i.ytimg.com/vi/${t.ytId}/hqdefault.jpg` : './music-cover.svg'),
    cover: t.cover || t.coverUrl || (t.ytId ? `https://i.ytimg.com/vi/${t.ytId}/hqdefault.jpg` : './music-cover.svg')
  }));
};

